mapper.select:

	
	    select * from(
	        select /*+INDEX_DESC(shop_book 인덱스ID)*/ rownum as rn, bookId, bookName,
	            (select authorName from shop_author where shop_book.authorId = shop_author.authorId) authorName, authorId,
	            (select cateName from shop_bcate where shop_book.cateCode = shop_bcate.cateCode) cateName,cateCode, publisher, publeYear, bookPrice  
	        from shop_book
	        where 
    
    
    
    
    
    		        
	        rownum <= #{pageNum} * #{amount} 
        	)
        where rn > (#{pageNum} -1) * #{amount}
